            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Everybody has a secret world inside of them. All of the people of the world, I mean everybody. No matter how dull and boring they are on the outside, inside them they've all got unimaginable, magnificent, wonderful, stupid, amazing worlds. Not just one world. Hundreds of them. Thousands maybe.", Author = "Neil Gaiman" },
