            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "If you actually pay any credence to it, it does make you crazy. So you just kind of smile and think, \"Maybe someday I'll review all the reviewers someday.\" But you probably won't.", Author = "Neil Gaiman" },
