            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "The world always seems brighter when you've just made something that wasn't there before.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Behind every Chesterton sentence there was someone painting with words, and it seemed to me that at the end of any particularly good sentence or any perfectly-put paradox, you could hear the author, somewhere behind the scenes, giggling with delight.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "And without those three writers, I would not be here today. And nor, of course, would any of you. I thank you.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Because if you don't stand up for the stuff you don't like, when they come for the stuff you do like, you've already lost.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "I tweet, therefore my entire life has shrunk to 140 character chunks of instant event and predigested gnomic wisdom. And swearing.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Honestly, if you're given the choice between Armageddon or tea, you don't say \"what kind of tea?\"", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Suddenly I got a very good idea of what it must feel like. I went: \"I'm writing it now this scene in the Tardis. I'm writing it!\" And that was amazing, it was wonderful.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "At best Doctor Who is a fairytale, with fairytale logic about this wonderful man in this big blue box who at the beginning of every story lands somewhere where there is a problem.", Author = "Neil Gaiman" },
