            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Men must not close our eyes and minds to what happens to women in this world. We must fight, alongside them, for them to be believed, at the ballot box & with art & by listening, and change this world for the better.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "In Hollywood the man who cleans your pool is an actor. The man who sells you your copy of Variety is an actor. I don't think there's a real person left in the place.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "The world is always ending, for someone.", Author = "Neil Gaiman" },
