            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "He had gone beyond the world of metaphor and simile into the place of things that are, and it was changing him.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "This is the kind of thing you wonder about when you make up things for a living.", Author = "Neil Gaiman" },
