            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "The little folk dare anything, And they talk a lot of nonsense. But they talks an awful lot of sense, as well. You listen to 'em at your peril, and you ignore 'em at your peril, too.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Gods die. And when they truly die they are unmourned and unremembered. Ideas are more difficult to kill than people, but they can be killed, in the end.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "There's never been a true war that wasn't fought between two sets of people who were certain they were in the right. The really dangerous people believe they are doing whatever they are doing solely and only because it is without question the right thing to do.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Fairy tales are more than true: not because they tell us that dragons exist, but because they tell us that dragons can be beaten.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "When you're scared but you still do it anyway, that's brave.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "But how can you walk away from something and still come back to it?", Author = "Neil Gaiman" },
