            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "I believe we owe it to each other to tell stories. It’s as close to a credo as I have or will, I suspect, ever get.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "If there’s one thing that a study of history has taught us, it is that things can always get worse,", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "New Orleans is a real place, which is more than I can say about most of the cities I’ve lived in, but it’s not a safe place, not a friendly one.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "But where does contagion end and art begin?", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "We save our lives in such unlikely ways.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "It was cold, in a way that Shadow was starting to become familiar with: colder inside the building than out. He wondered how they did that, if it was a British building secret.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "If they think you're a hero, they're wrong. After you die, you don't get to be Beowulf or Perseus or Rama any more. Whole different set of rules. Chess, not checkers. Go, not chess. You understand?", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "At the best of times his face was unreadable. Now his face was a book written in a language long forgotten, in an alphabet unimagined. Silas wrapped the shadows around him like a blanket, and stared after the way the boy had gone, and did not move to follow.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "People want to forget the impossible. It makes their world safer.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "I want to see life. I want to hold it in my hands. I want to leave a footprint on the sand of a desert island. I want to play football with people. I want, and then he paused, and thought. \"I want everything.\"", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Google can bring you back, you know, a hundred thousand answers. A librarian can bring you back the right one.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "I lived in books more than I lived anywhere else.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Adults rarely seemed to believe me when I told the truth anyway. Why would they believe me about something so unlikely?", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "I liked myths. They weren't adult stories and they weren't children's stories. They were better than that. They just were.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "I went away in my head, into a book. That was where I went whenever real life was too hard or too inflexible.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Children, as I have said, use back ways and hidden paths, while adults take roads and official paths.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Just go with it. It won’t hurt. I stared at him. Adults only ever said that when it, whatever it happened to be, was going to hurt so much.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "I was a normal child. Which is to say, I was selfish and I was not entirely convinced of the existence of things that were not me, and I was certain, rock-solid unshakably certain, that I was the most important thing in creation. There was nothing that was more important to me than I was.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Nothing’s ever the same. Be it a second later or a hundred years. It’s always churning and roiling. And people change as much as oceans.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "Fiction is the lie that tells the truth, after all.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "The truth is, individuals change their world over and over, individuals make the future, and they do it by imagining that things can be different.", Author = "Neil Gaiman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Neil_Gaiman", Text = "One of the things I love about Kate Bush is her absolute ability to take things, to pluck things that you would never expect to see on a rock album, and put them there and make them work.", Author = "Neil Gaiman" },
